#include <nadir/astro/crd.hpp>
#include <cmath>
#include <sstream>
namespace nadir::astro { CrdParseResult parse_crd_normal_points(const std::string& text){constexpr std::size_t limit=16U*1024U*1024U;if(text.size()>limit)return{false,{},"CRD exceeds size limit"};std::istringstream in(text);std::string line,type;bool h1{},h2{},h3{},h4{},h8{},h9{};std::vector<CrdNormalPoint> out;while(std::getline(in,line)){std::istringstream f(line);if(!(f>>type)||type=="00")continue;if(type=="H1"){h1=true;continue;}if(type=="H2"){h2=true;continue;}if(type=="H3"){h3=true;continue;}if(type=="H4"){h4=true;continue;}if(type=="H8"){h8=true;continue;}if(type=="H9"){h9=true;break;}if(type!="11")continue;CrdNormalPoint p;double rms{},skew{},kurtosis{},peak{},rate{},snr{};if(!h1||!h2||!h3||!h4||!(f>>p.seconds_of_day>>p.time_of_flight_s>>p.system_id>>p.epoch_event>>p.window_s>>p.raw_ranges>>rms>>skew>>kurtosis>>peak>>rate>>p.detector_channel>>snr)||p.seconds_of_day<0||p.seconds_of_day>86400||p.time_of_flight_s<0||p.time_of_flight_s>3||p.epoch_event<0||p.epoch_event>6||p.window_s<0||p.window_s>300||p.raw_ranges<0||p.detector_channel<0||p.detector_channel>9||!std::isfinite(p.seconds_of_day)||!std::isfinite(p.time_of_flight_s))return{false,{},"invalid CRD normal point"};out.push_back(p);}if(!h1||!h2||!h3||!h4||!h8||!h9||out.empty())return{false,{},"missing CRD headers, normal points, or footers"};return{true,std::move(out),{}};} }
